// Generated LDCE MCQs for PO Regulations 2024
import { Question } from "@/lib/quizTypes";

export const po_reg_ldce_set1: any[] = [
  { q: "Which of the following is NOT considered an \"accountable item\" as per the Post Office Regulations, 2024?", o: ["India Post Parcel","Speed Post","Magazine Post","Book Post"], a: 3, e: "• Concept: Regulation 2(a) defines \"accountable items\" as those providing a receipt at booking for track and trace, requiring a signature upon receipt, and lists examples such as India Post Parcel, Speed Post, Magazine Post, International Speed Post Services (EMS), International Air Parcels, International Tracked Packets, International Registered Letter items, Money Order, and items with value-added services like registration, insurance, and cash on delivery (COD). • Elimination: Book Post is not listed among the examples of accountable items; it is typically an unaccountable item posted in letter boxes." },
  { q: "On which date did the Post Office Regulations, 2024, come into force?", o: ["December 16, 2023","January 1, 2024","December 16, 2024","January 1, 2025"], a: 2, e: "• Concept: Regulation 1(2) explicitly states, \"They shall come in to force on the 16th day of December, 2024.\" • Elimination: The other dates are incorrect based on the provided text." },
  { q: "What is the maximum period for which Branch Post Offices shall be kept open in a day, as per the Post Office Regulations, 2024?", o: ["Six hours","Seven hours","Five hours","Eight hours"], a: 2, e: "• Concept: Regulation 3(2) specifies that \"Branch post offices shall be kept open for a maximum period of five hours in a day.\" • Elimination: Six hours is for normal weekdays for counter services, money remittance, and savings bank in other post offices, not specifically Branch Post Offices." },
  { q: "As per the Post Office Regulations, 2024, what is the consequence for any person or entity selling or distributing postage stamps without the prior permission of the Director General?", o: ["A warning notice","A monetary fine of ₹1000","Punishable under the relevant provisions of the applicable law of the land","Confiscation of stamps only"], a: 2, e: "• Concept: Regulation 8(2) prohibits selling or distributing postage stamps without the Director General's prior permission. Regulation 8(3) states that \"Whoever contravenes the provisions of sub-regulation (2) above or any term or condition of permission issued thereunder shall be punishable under the relevant provisions of the applicable law of the land for the time being in force.\" • Elimination: The regulations do not specify a warning notice, a fixed monetary fine, or mere confiscation; they refer to punishment under applicable law." },
  { q: "The period \"in course of transmission by post\" begins from the receipt of an item by the post office and ends at which point?", o: ["Its dispatch from the originating post office","Its arrival at the destination post office","Its delivery to the addressee or return to the sender or otherwise disposed of","The sorting of the item at the mail office"], a: 2, e: "• Concept: Regulation 2(h) defines \"in course of transmission by post\" as \"the period starting from receipt of an item by the post office to its delivery to the addressee or return to the sender or otherwise disposed of.\" • Elimination: The other options describe intermediate stages, not the full defined period." },
  { q: "Which of the following items, if posted in a letter box, shall be treated as unpaid and dealt with as per regulation 71?", o: ["Letters","Postcards","Registered newspaper items","Book post"], a: 2, e: "• Concept: Regulation 22(a) Note 1 explicitly states, \"Registered newspaper items, periodical post items and franked items shall not be posted in these letter boxes and, if posted, these shall be treated as unpaid and shall be dealt as per regulation 71.\" • Elimination: Letters, postcards, and book post are listed as items that *can* be posted in letter boxes if fully prepaid." },
  { q: "What is the maximum number of characters allowed per line in an address for both domestic and international items, excluding spaces between words, as per the Post Office Regulations, 2024?", o: ["30 characters","40 characters","50 characters","60 characters"], a: 1, e: "• Concept: Regulation 18(11) for domestic items and Regulation 21(12) for international items both state, \"The maximum number of characters per line is 40 characters, excluding spaces between words.\" • Elimination: The other options are incorrect values." },
  { q: "Which type of postage stamp is issued to commemorate an event, institution, theme, and personages, printed only once in limited numbers, and sold for a limited period?", o: ["Definitive Stamps","Special Stamps","Commemorative Stamps","My Stamps"], a: 2, e: "• Concept: Regulation 13(b)(i) describes Commemorative Stamps as \"postage stamps issued to commemorate an event, institution, theme and personages, which shall be printed only once, in limited numbers and are sold for a limited period...\" • Elimination: Definitive stamps are for day-to-day needs and reprinted. Special stamps are thematic without commemorating a specific event. My Stamps are personalized." },
  { q: "According to the Post Office Regulations, 2024, under what condition is the issuance of a postage stamp explicitly prohibited?", o: ["On an event that occurred less than 5 years ago","On a living personality","Without prior approval from the Philatelic Advisory Committee","If the design includes a national symbol"], a: 1, e: "• Concept: Regulation 14(5) clearly states, \"No postage stamp shall be issued on a living personality.\" • Elimination: The other options are not explicitly stated as prohibitions in the provided text." },
  { q: "Who is empowered to determine the prices of Special Rakhi Envelopes as per the Post Office Regulations, 2024?", o: ["The Director General","The Central Government","The Circle Head concerned","The Regional Head"], a: 2, e: "• Concept: Regulation 17(3) states, \"Special Rakhi Envelopes shall be sold at the prices as the Circle Head concerned may determine.\" • Elimination: The Director General, Central Government, or Regional Head are not specified for this particular determination." },
  { q: "For domestic items, where should the address of the addressee and the address of the sender be written on an envelope, respectively?", o: ["Addressee: upper right, Sender: lower left","Addressee: centre of front side, Sender: lower left of front side","Addressee: upper left, Sender: lower right","Addressee: centre of front side, Sender: upper right of front side"], a: 1, e: "• Concept: Regulation 18(3) specifies, \"The address of the addressee shall be written in the centre of the front side and address of the sender shall be written on the lower left of the front side of an envelope.\" • Elimination: The other options describe incorrect placements." },
  { q: "Which of the following items is explicitly prohibited from being sent by post under the Post Office Regulations, 2024, unless organised or authorised by the Central Government or State Government?", o: ["Any sharp instrument not properly protected","Any item having words of a threatening character","Any ticket, proposal, advertisement or any other matter relating to a lottery","Any pictorial representation of a person convicted of an offence"], a: 2, e: "• Concept: Regulation 25(1)(c) prohibits \"any ticket, proposal, advertisement or any other matter relating to a lottery, except the case where the lottery is organised or authorised by the Central Government or State Government.\" The other options are also prohibited but do not have the specific exception mentioned in the question. • Elimination: While other options are also prohibited, the specific condition of \"unless organised or authorised by the Central Government or State Government\" applies uniquely to lottery-related items among the choices provided." },
  { q: "An item addressed to the CVC or CVOs with the superscription 'Complaint under the Public Interest Disclosure' or 'PIDPI Complaint' can be accepted for transmission by post under what special condition?", o: ["Only if the sender's full address is provided","Without the name and complete address of the sender","Only if booked at a Head Post Office","With an additional special handling fee"], a: 1, e: "• Concept: Regulation 20 states, \"Any item, addressed to the CVC as well as CVOs, posted with the superscription 'Complaint under the Public Interest Disclosure\" or \"PIDPI Complaint\" on the outside of the envelope of the item, may be accepted for transmission by post, without the name and complete address of the sender.\" • Elimination: The regulation specifically allows for the absence of the sender's name and address, contradicting the first option. No mention of specific post office type or additional fee." },
  { q: "For domestic items, when does the ownership of an item generally transfer from the sender to the addressee, according to the Post Office Regulations, 2024?", o: ["Upon booking at the post office","Upon dispatch from the originating post office","Upon delivery to the rightful addressee","Upon payment of postage"], a: 2, e: "• Concept: Regulation 24(1) states, \"For domestic items, an item shall remain the property of the sender until it is delivered to the rightful addressee, except in the case of seizure of the item under the applicable law of the land for the time being in force.\" • Elimination: Ownership remains with the sender until delivery, not at booking, dispatch, or payment." },
  { q: "Under which of the following circumstances shall postage and other sums chargeable on an item NOT be deemed to be prepaid by means of a proper stamp or franking impression?", o: ["The stamp has been perforated with initials","The stamp has been cut from an embossed envelope","The item is a Book Now Pay Later (BNPL) item","The stamp is affixed to the right-hand top corner"], a: 1, e: "• Concept: Regulation 7(d) states that postage is not deemed prepaid if \"the stamp has been cut, or otherwise, separated from an embossed envelope, or from a postcard or wrapper.\" The first proviso of Regulation 7 allows for perforation with initials, and the second proviso allows for BNPL items. Affixing to the right-hand top corner is the correct manner of affixing stamps (Reg 16(2)). • Elimination: Perforation with initials and BNPL items are explicitly allowed exceptions. Affixing to the right-hand top corner is the correct method, not a reason for non-prepayment." },
  { q: "According to the Post Office Regulations, 2024, which of the following is NOT explicitly included in the definition of \"dangerous goods\"?", o: ["Explosives","Gases","Flammable liquids","Radioactive materials"], a: 3, e: "• Concept: Regulation 25(l) Explanation defines \"dangerous goods\" as items or substances capable of posing a risk to health, safety, property or environment, including explosives, gases, flammable liquids, toxic and infectious substances, corrosives and other miscellaneous items. • Elimination: Radioactive materials are not explicitly listed in the provided definition, although they would likely fall under \"toxic and infectious substances\" or \"miscellaneous items\" in a broader sense, the question asks what is *not explicitly included*." },
  { q: "A customer who has been allotted a Post Box must inform the Postmaster concerned about a change in their business address within how many days of such change?", o: ["3 days","7 days","15 days","30 days"], a: 1, e: "• Concept: Regulation 46(2)(b) states that in case of change in business address, the customer shall invariably inform the Postmaster concerned regarding the change within seven days of such change. • Elimination: Options 0, 2, and 3 are incorrect as the regulation specifically mentions \"seven days\"." },
  { q: "What is the additional postal fee charged from the addressee for customs clearance of each foreign letter packet or insured box, if released after levying customs duty?", o: ["Rupees ten","Rupees twenty","Rupees thirty","Rupees fifty"], a: 2, e: "• Concept: Regulation 31(3) and the \"CUSTOM CLEARANCE\" table specify that a fee of \"Rupees thirty\" is recoverable from the addressee for each foreign letter packet or insured box if released after levying customs duty. • Elimination: The other options are incorrect amounts as per the regulation." },
  { q: "As per the Post Office Regulations, 2024, currency notes, coins, or bank notes, when permitted for transmission, shall invariably be transmitted in what manner?", o: ["As ordinary letter post items","As registered items","As insured items","As speed post items"], a: 2, e: "• Concept: Regulation 25(n) states: \"Provided further that currency notes, coins, or bank notes, shall invariably be transmitted as insured items\". • Elimination: While registered or speed post items offer tracking, the regulation specifically mandates insurance for these valuable items. Ordinary letter post is explicitly not allowed." },
  { q: "An application for the renewal of the allotment of a post box must be made to the Postmaster concerned at least how many days before the expiry of the period for allotment?", o: ["7 days","10 days","15 days","30 days"], a: 2, e: "• Concept: Regulation 46(3) states that application for the renewal of the allotment of a post box shall be made to the Postmaster concerned at least 15 days before the expiry of the period for allotment. • Elimination: The other options are incorrect as the regulation specifies \"15 days\"." },
  { q: "If a customer fails to inform the Postmaster concerned about a lost or damaged key or lock of their allotted Post Box within the stipulated timeframe, what is the consequence?", o: ["A penalty equal to the annual fee will be levied.","The post box will be withdrawn immediately.","The security deposit made by the customer shall be forfeited.","The customer will be charged double the replacement cost."], a: 2, e: "• Concept: Regulation 46(5)(b)(ii) states that if the customer fails to bring the matter to the notice of the Postmaster concerned within 7 days and credit the cost of repairing or replacing the lock, key, or both, \"the deposit made by him shall be forfeited.\" • Elimination: While withdrawal might be a subsequent action, the immediate consequence mentioned for failure to inform and credit cost is forfeiture of the security deposit." },
  { q: "What is the fee for renting a Post Box or Post Bag separately for a period of three calendar months or part thereof, if rented for less than a full financial year?", o: ["Rs. 150","Rs. 50","Rs. 80","Rs. 250"], a: 1, e: "• Concept: The \"Post Box and Post Bag Fees\" table under Regulation 46(5) specifies that for Post Boxes or Bags taken separately, if rented for three calendar months or part thereof, the fee is \"50\" Rupees. • Elimination: The other options correspond to different rental periods or combined services." },
  { q: "Which of the following live animals are permitted to be transmitted in letter post items (other than insured items) between officially recognised institutions, as per the Post Office Regulations, 2024?", o: ["Small birds","Pet fish","Bees, leeches, and silk-worms","Reptiles"], a: 2, e: "• Concept: Regulation 27(b)(i) explicitly lists \"bees, leeches and silk-worms; parasites and destroyers of noxious insects intended for the control of those insects and exchanged between officially recognised institutions; flies of the family Drosophilidae for biomedical research exchanged between officially recognised institutions\" as exceptions for live animals in letter post items. • Elimination: Small birds, pet fish, and reptiles are not listed as permitted in letter post items." },
  { q: "If an accountable international item is received in a damaged condition, a notice shall be sent to the addressee requesting them to attend the post office within how many days to take delivery?", o: ["7 days","10 days","15 days","30 days"], a: 2, e: "• Concept: Regulation 52 states that for an international item received in a damaged condition, a notice shall be sent to the addressee requesting him to attend the post office within \"fifteen days\". For domestic items, it is seven days. • Elimination: Options 0, 1, and 3 are incorrect for international items." },
  { q: "An accountable item, if not delivered on its first presentation, shall be issued for delivery once again. In case of inability to deliver after how many attempts, it shall in no case be issued again for delivery?", o: ["One attempt","Two attempts","Three attempts","Four attempts"], a: 1, e: "• Concept: Regulation 42(1) states: \"An accountable item shall be issued for delivery and if it is not delivered due to any reason on its first presentation, it shall be issued once again for delivery. In case of inability to deliver after two attempts, it shall, in no case, be issued again for delivery.\" This means 1st attempt + once again (2nd attempt). • Elimination: The regulation clearly specifies \"after two attempts\"." },
];

export const po_reg_ldce_set2: any[] = [
  { q: "What is the postal fee payable by the sender for availing the facility of recalling an accountable domestic item from the post or altering its address?", o: ["Rs. 5/-","Rs. 6/-","Rs. 10/-","No fee is charged"], a: 1, e: "• Concept: Regulation 55(1) states that the sender of an item may avail the facility for accountable domestic and international inward items \"by paying a postal fee Rs. 6/-\". • Elimination: The other options are incorrect as the regulation specifies \"Rs. 6/-\"." },
  { q: "Under what specific condition can an item for the blind, transmitted as printed papers and literature for the blind, contain a paper representing a monetary value?", o: ["If it is a cheque payable to the sender.","If it contains a prepaid card, envelope, or wrapper for return.","If the monetary value is less than Rs. 100.","Such items are strictly prohibited from containing any monetary value paper."], a: 1, e: "• Concept: Regulation 29(b) prohibits items for the blind from containing any postage stamp or form of prepayment, whether cancelled or not, or any paper representing a monetary value, \"except in cases where the item contains as an enclosure, a card, envelope or wrapper, bearing the printed address of the sender of the item or his authorised person in the country or territory of posting or destination of the original item, which is prepaid for return.\" • Elimination: The other options are not exceptions mentioned in the regulation." },
  { q: "How are unpaid or insufficiently paid items delivered according to the Post Office Regulations, 2024?", o: ["They are returned to the sender immediately.","They are delivered only after collection of the required postage.","They are delivered free of charge as a goodwill gesture.","They are held at the post office for 7 days for collection by the addressee."], a: 1, e: "• Concept: Regulation 44(8) states: \"The delivery of the unpaid or insufficiently paid items shall be made only after collection of the postage, required to be collected.\" • Elimination: The items are not returned immediately, nor are they delivered free of charge or held without specific instruction for collection." },
  { q: "If the outward appearance of the cover of an accountable item is suspected to be tampered with, what is the prescribed procedure at the post office?", o: ["The item is immediately returned to the sender.","The item is opened at the post office in the presence of the Postmaster, and contents are inventoried.","The addressee is asked to sign a declaration stating the item was received tampered.","The item is forwarded to the nearest police station for investigation."], a: 1, e: "• Concept: Regulation 43(2) states: \"Where the outward appearance of the cover of the accountable item is suspected to be tempered, the item shall be opened at the post office, in the presence of the Postmaster, and to have its contents entered in an inventory, which shall be prepared in duplicate and shall be signed by the addressee.\" • Elimination: The item is not immediately returned, nor is a declaration signed without opening, nor is it directly forwarded to the police station without internal procedure." },
  { q: "Which of the following items, if transmitted by post, shall in no case be sent in an uninsured letter-post item?", o: ["Printed books","Commercial papers","Precious metals","Small packets"], a: 2, e: "• Concept: Regulation 28(1) explicitly states: \"Precious metals (including gold, silver, platinum or other precious metals), precious stones (including diamond or other precious stones), jewellery or any combination of these, whether manufactured or not, coins, bank notes, currency notes, securities of any kind payable to bearer, travellers' cheques, except as otherwise specified, shall, in no case, be transmitted by post in an uninsured letter-post item.\" • Elimination: Printed books, commercial papers, and small packets are generally not considered items that *must* be insured when sent as letter-post." },
  { q: "As per Post Office Regulations, 2024, an item shall ordinarily be kept in deposit in the post office to which it is addressed for a period of ______ after all enquiries to find the addressee have proved unsuccessful.", o: ["3 days","7 days","15 days","30 days"], a: 1, e: "• Concept: Regulation 64(1) states, \"An item shall ordinarily be kept in deposit in the post office to which it is addressed for a period of seven days after all enquiries to find the addressee have proved unsuccessful.\"\n• Elimination: Other options are incorrect as per the specified regulation. 3 days, 15 days, and 30 days are not the standard deposit period at the delivery post office for undelivered items after unsuccessful inquiries." },
  { q: "If a domestic letter infringes the conditions mentioned in Regulation 87 and sub-regulation (1) to (13) of Regulation 88 of the Post Office Regulations, 2024, what will be the charge levied?", o: ["Single the deficiency in postage","Double the postage and any postage paid on it shall be taken into account","Double the deficiency in postage","A flat penalty of ₹10/-"], a: 1, e: "• Concept: Regulation 88(14) states, \"In case of infringement of the conditions mentioned in regulation 87 and sub regulation (1) to (13) of regulation 88, the letter shall be charged with double the postage and any postage paid on it shall be taken into account in assessing the charges.\"\n• Elimination: Options suggesting single deficiency or a flat penalty are incorrect. Double the deficiency applies to insufficiently paid items (Reg 71) or letter cards infringing conditions (Reg 90), but for general letter infringements of Reg 87/88, it's double the postage, with paid postage accounted for." },
  { q: "What is the maximum compensation payable for a domestic registered item in case of loss, abstraction, or damage, as per the Post Office Regulations, 2024?", o: ["₹ 50/-","₹ 100/- or the actual value of contents, whichever is less","₹ 500/-","Double the registered post charges"], a: 1, e: "• Concept: Regulation 74(1) specifies, \"The compensation to be paid in respect of domestic registered items shall be Subject to a maximum of Rs. 100/- (Rupees One Hundred) or the actual value of contents, whichever is less.\"\n• Elimination: Other amounts are incorrect for domestic registered items. ₹500 is for India Post Parcel or VPP/COD loss. Double the charges is for Speed Post loss or unpaid/insufficiently paid items." },
  { q: "As per Regulation 67 of the Post Office Regulations, 2024, for how long shall accountable items that remain undelivered to the address as well as the sender be detained at the Returned Letter Office (RLO)?", o: ["7 days","15 days","30 days","45 days"], a: 2, e: "• Concept: Regulation 67(b) states that items detained at RLO shall be kept for \"thirty days when they are accountable.\"\n• Elimination: 7 days is for detention at the delivery post office (Reg 64). 15 days is for unaccountable items at RLO (Reg 67(a)) or Poste Restante items (Reg 66 table). 45 days is not mentioned." },
  { q: "If an unpaid item of foreign post, which has not been impressed with the T-stamp by the office of origin and has not been taxed by the foreign post office through obvious error, is received in a post office for delivery, what is the prescribed action?", o: ["It shall be delivered as fully prepaid.","It shall be taxed by the receiving post office and delivered.","It shall be sent back to the foreign post office concerned to be properly taxed and delivered on receipt back.","It shall be sent to the Returned Letter Office immediately."], a: 2, e: "• Concept: Regulation 60(3) states, \"If an unpaid item of the foreign post, which has not been impressed with the T - stamp by the office of origin and has not been taxed by the foreign post office through obvious error, is received in a post office for delivery, then such item shall be sent back to the foreign post office concerned to be properly taxed and shall be delivered on receipt back after recovery of the postage due.\"\n• Elimination: Delivering as fully prepaid applies only if phrases like \"Tax persue\" or \"Port paye\" are present without an amount. The receiving post office cannot tax foreign post items directly (Reg 60(2)). Sending to RLO is for undeliverable items after other attempts." },
  { q: "For what maximum period does a written intimation regarding a change in residential or official address remain valid for delivery of items, as per the Post Office Regulations, 2024?", o: ["One month","Two months","Three months","Six months"], a: 2, e: "• Concept: Regulation 69(2) states, \"Such intimation shall remain valid for a period not exceeding three months.\"\n• Elimination: Other options are incorrect as per the regulation." },
  { q: "What is the charge for an unpaid domestic item on delivery, as per the Post Office Regulations, 2024?", o: ["Single the prepaid rate","Double the prepaid rate","Double the deficiency","Rupee one, irrespective of the prepaid rate"], a: 1, e: "• Concept: Regulation 71, Table (i) states, \"On an unpaid item: Double the prepaid rate.\"\n• Elimination: Double the deficiency is for insufficiently paid items. Single prepaid rate is incorrect. Rupee one is the minimum charge, not the general rule for unpaid items." },
  { q: "For loss of a domestic Speed Post item, abstraction of content, loss of content, damage to content, or damage to item, what is the compensation payable as per the Post Office Regulations, 2024?", o: ["Speed Post charges","Double the Speed Post charges or ₹500/-, whichever is less","Double the Speed Post charges or ₹1,000/-, whichever is less","₹100/- or the actual value of contents, whichever is less"], a: 2, e: "• Concept: Regulation 75(1)(a) states, \"For loss of item, abstraction of content, loss of content, damage to content or damage to item: Double the Speed Post charges or Rs. 1,000/- (Rupees One Thousand), whichever is less.\"\n• Elimination: Speed Post charges alone are for delay in delivery. ₹500 is for India Post Parcel or VPP/COD loss. ₹100 is for domestic registered items." },
  { q: "As per Regulation 68(1)(d) of the Post Office Regulations, 2024, which of the following undelivered items shall be destroyed forthwith?", o: ["Items without intrinsic value containing printed papers","Magazines, periodicals and newspapers","Items with intrinsic value","Postcards and letter cards on which the postage has not been prepaid"], a: 3, e: "• Concept: Regulation 68(1)(d) explicitly states, \"postcards and letter cards on which the postage has not been prepaid shall be destroyed forthwith.\"\n• Elimination: Items without intrinsic value are disposed of by selling as waste paper or destroyed (68(1)(a)). Magazines, periodicals, and newspapers may be used for public purpose (68(1)(b)). Items with intrinsic value are disposed of through auction (68(1)(c))." },
  { q: "When an international item is refused by the addressee, how is it disposed of according to the Post Office Regulations, 2024?", o: ["It is returned at once direct to the office of posting for delivery to the sender.","It is sent to the Returned Letter Office.","It is returned to the foreign post office for further disposal.","It is destroyed immediately."], a: 2, e: "• Concept: Regulation 62(3) states, \"In respect of international item, such item shall be returned to the foreign post office for further disposal.\"\n• Elimination: Options (a) and (b) apply to domestic unclaimed/refused items (Reg 62(2)). Immediate destruction is for specific cases like unpaid postcards/letter cards or public good (Reg 68)." },
  { q: "What is the time limit for claiming compensation for a domestic item from the date of booking, as per the Post Office Regulations, 2024?", o: ["One month","Three months","Six months","One year"], a: 1, e: "• Concept: Regulation 83(a) states, \"For domestic items: Three months.\"\n• Elimination: Six months is for international items. Other options are incorrect." },
  { q: "What is the compensation payable for an International Air Parcel as per the Post Office Regulations, 2024?", o: ["30 SDR","40 SDR per parcel plus 4.50 SDR per kg","Insured value or actual value, whichever is less","Double the International Air Parcel charges"], a: 1, e: "• Concept: Regulation 78 states, \"The compensation to be paid in respect of International Air Parcel shall be 40 SDR per parcel plus 4.50 SDR per kg.\"\n• Elimination: 30 SDR is for International Registered items, International Speed Post (EMS) loss, or International Tracked Packet. Insured value is for insured items. Double the charges is not specified for International Air Parcel." },
  { q: "When a postage-due stamp is impressed on an item, whose initials must be mentioned under the amount shown by the impression of the postage due stamp of the office of dispatch?", o: ["The Postman or the authorised delivery person","The sender of the item","The Postmaster or the officer in-charge or the authorised office or official","The Circle Head or the Regional Head concerned"], a: 2, e: "• Concept: Regulation 60(1) states, \"The postage-due stamp shall be impressed on the items mentioned in regulation 59 and the amount shown by the impression of the postage due stamp of the office of dispatch shall be mentioned under the initials of the Postmaster or the officer in-charge or the authorised office or official.\"\n• Elimination: The Postman/delivery person makes official marks for non-delivery reasons (Reg 70), but not specifically for postage due stamp initials. Sender is not involved in this. Circle Head/Regional Head are involved in RLO item disposal." },
  { q: "According to the \"Standard Remarks and Procedures\" table in Regulation 66, what is the final disposal of an article marked \"Addressee not found\"?", o: ["Returned to sender immediately","Redirected on the same day","Keep in deposit for 7 days and if nobody claims, returned to sender","Sent to the Returned Letter Office"], a: 2, e: "• Concept: The table under Regulation 66, Sl. No. 2 for \"Addressee not found\" states the final disposal as \"Keep in deposit for 7 days and if nobody claims, returned to sender\".\n• Elimination: \"Returned to sender immediately\" applies to \"Refused\", \"Addressee left without instructions\", \"Premises Locked\", \"Insufficient Address\", \"Unclaimed\", \"Deceased\", \"No Such Person\", \"Poste Restante (after 15 days)\". \"Redirected on the same day\" is for \"Redirected\". \"Sent to RLO\" is typically if sender cannot be found or for international items." },
  { q: "If a letter card infringes the conditions specified in Regulation 89, how will it be charged on delivery?", o: ["As a letter, with double the postage for a letter.","As a letter, with double the deficiency between the postage paid for such letter card and the postage payable for a letter.","As a letter, with single the deficiency between the postage paid for such letter card and the postage payable for a letter.","It will be returned to the sender without charge."], a: 1, e: "• Concept: Regulation 90(1) states, \"In case of infringement of the conditions specified in regulation 89, the letter card shall be treated as a letter and charged on delivery with double the deficiency between the postage already paid for such letter card and the postage payable for a letter.\"\n• Elimination: Option (a) is incorrect as it's not double the full postage for a letter, but double the *deficiency*. Option (c) is incorrect as it's double, not single, the deficiency. Option (d) is incorrect as it will be charged on delivery." },
  { q: "If a postcard infringes any of the specified conditions, it shall be treated as a letter and charged on delivery with double the deficiency between the postage already paid and the postage payable for a letter. What is the minimum charge for such an infringement, and how is it handled if the amount is a part of a rupee containing paise?", o: ["₹0.50, and if it contains paise, the amount shall be increased to ₹1.","₹1, and if it contains paise, the amount shall be increased to ₹2.","₹1, and if it contains paise, the amount shall be increased to ₹1.","₹2, and if it contains paise, the amount shall be increased to ₹2."], a: 2, e: "• Concept: Regulation 91(2) specifies the penalty for postcard infringement. It states that the charge is 'subject to a minimum of one rupee, and where such amount is a part of a rupee containing paise, the amount shall be increased to one rupee.'\n• Elimination: Options suggesting a minimum of ₹0.50 or ₹2 are incorrect. The specific handling of paise (increasing to one rupee) is crucial, making option 2 the only correct choice." },
  { q: "What is the maximum permissible weight for an item transmitted by post as a 'book post'?", o: ["2 kilograms","3 kilograms","5 kilograms","10 kilograms"], a: 2, e: "• Concept: Regulation 92(1)(a) defines the weight limit for book post items.\n• Elimination: The regulation clearly states 'a book post shall not exceed 5 kilograms in weight'. Therefore, any other weight limit is incorrect." },
  { q: "What is the minimum weight required for booking a packet under the 'Gyan Post' category?", o: ["100 grams","200 grams","300 grams","500 grams"], a: 2, e: "• Concept: Regulation 92A(9) specifies the weight limits for Gyan Post items.\n• Elimination: The regulation explicitly states 'The minimum weight for booking packet under \"Gyan Post\" shall be three hundred gms.' Options 0, 1, and 3 are incorrect as per the regulation." },
  { q: "Within how many days from the receipt of the application form shall postal registration be granted to a newspaper for transmission as a Registered Newspaper?", o: ["7 days","15 days","30 days","60 days"], a: 2, e: "• Concept: Regulation 95(1) outlines the timeline for granting postal registration to a newspaper.\n• Elimination: The text clearly states 'Postal registration shall be granted to a newspaper within 30 days from the receipt of application form.' Other timelines are incorrect." },
  { q: "What is the late fee charged for an application for renewal of Registered Newspaper registration received later than the last working day of the third calendar month preceding the last month of the period of previous registration?", o: ["₹25","₹50","₹100","No late fee"], a: 1, e: "• Concept: Regulation 95(1) details the late fees for renewal applications of Registered Newspapers.\n• Elimination: The regulation specifies 'A late fee of Rs. 50/- shall be charged for each application for renewal received later than the last working day of the third calendar month preceding the last month of the period of previous registration.' The ₹100 fee applies if received after expiry, and there is no fee for timely renewal." },
];

export const po_reg_ldce_set3: any[] = [
  { q: "What is the maximum weight allowed for an item transmitted as 'Literature for the Blind'?", o: ["2 kilograms","5 kilograms","7 kilograms","10 kilograms"], a: 2, e: "• Concept: Regulation 93(1)(d) specifies the weight limit for 'Literature for the Blind' items.\n• Elimination: The regulation clearly states 'the weight of a \"Literature for the Blind\" item shall not exceed 7 kilograms'. Other options are incorrect." },
  { q: "If a Periodical Post item infringes any of the conditions specified in sub-regulation (1) and (3) of Regulation 94, how shall the item be treated and charged?", o: ["As a letter post item","As an India Post Parcel item","As a book post item","As a registered newspaper"], a: 2, e: "• Concept: Regulation 94(4) describes the consequence of infringement for Periodical Post items.\n• Elimination: The regulation explicitly states 'the item shall be treated and charged as a book post item and any postage paid on it shall be taken into account in assessing the charges.' Therefore, treating it as a letter, parcel, or registered newspaper is incorrect." },
  { q: "What is the maximum gross weight for an India Post Parcel?", o: ["20 kgs","25 kgs","30 kgs","35 kgs"], a: 3, e: "• Concept: Regulation 96(2)(d) specifies the maximum weight for an India Post Parcel.\n• Elimination: The regulation states 'whose gross weight does not exceed 35 kgs or volumetric weight as defined'. Options 0, 1, and 2 are below the specified maximum." },
  { q: "Which of the following is explicitly prohibited from being contained in a packet sent as 'Gyan Post'?", o: ["Textbooks for competitive examinations","Literature related to social, cultural, and religious nature","Publications published at regular intervals (e.g., magazines, journals)","Books containing the name of the printer or publisher"], a: 2, e: "• Concept: Regulation 92A(2) lists conditions for Gyan Post, including prohibitions.\n• Elimination: Regulation 92A(2)(a) states 'They shall not contain any publication, published at regular intervals; Illustration- Magazines, journal or similar publication issued at a regular interval of time weekly, fortnightly, monthly, bi-monthly, quarterly, half yearly and so- on.' The other options are either permitted or mandatory conditions." },
  { q: "What is the security deposit required for a Registered Newspaper to avail the facility of posting without prepayment (WPP)?", o: ["Equivalent to one week's postage","Equivalent to half a month's postage","Equivalent to the total of one month's postage","Equivalent to two months' postage"], a: 2, e: "• Concept: Regulation 95(2) under the section 'Security for WPP' specifies the required deposit.\n• Elimination: The text clearly states 'Equivalent to the total of one month postage as security deposit.' Other options are incorrect." },
  { q: "Which of the following items is NOT permitted to be affixed to a postcard as per Post Office Regulations, 2024?", o: ["A gummed label bearing the name and address of the sender not exceeding 50 mm in length and 20 mm in width, affixed to the back or left-hand half of the address side.","Engravings, illustrations, drawings, and photographs on very thin paper and completely adherent to the card.","A gummed label completely adherent to the card, bearing the name and address of the person to whom the card is sent, affixed to the address side.","A small metal charm attached to the corner of the card."], a: 3, e: "• Concept: Regulation 91(1) lists the specific items that are permitted to be affixed to a postcard.\n• Elimination: Sub-clauses (ii), (iii), and (iv) of Regulation 91(1) explicitly permit options 0, 1, and 2 respectively. A 'small metal charm' is not mentioned as a permitted item and would violate the general nature of a postcard as an open communication, making it the incorrect option." },
  { q: "What is the postage rate for a Book Post item weighing 120 grams?", o: ["₹4","₹7","₹10","₹13"], a: 2, e: "• Concept: Regulation 92(3) provides the rates for Book Post.\n• Elimination: The rates are: ₹4 for the first 50 grams or fraction thereof, and ₹3 for every additional 50 grams or fraction thereof. For 120 grams:\n    - First 50g: ₹4\n    - Next 50g (51-100g): ₹3\n    - Remaining 20g (101-120g, treated as a fraction of 50g): ₹3\n    - Total = ₹4 + ₹3 + ₹3 = ₹10." },
  { q: "For how long does every subsequent renewal of a Registered Newspaper's postal registration remain in force?", o: ["One calendar year","Two calendar years","Three calendar years","Five calendar years"], a: 2, e: "• Concept: Regulation 95(1) specifies the validity period for subsequent renewals of Registered Newspaper registration.\n• Elimination: The text states 'Every subsequent renewal of registration shall remain in force for three calendar years.' The initial registration has a different validity period, but the question specifically asks about subsequent renewals." },
  { q: "What is a distinctive feature of Logistics Post compared to Speed Post Parcel and India Post Parcel?", o: ["It is exclusively for government departments.","It has no specific weight limit for parcels.","It only offers door-to-door delivery.","It is transmitted only by air mode."], a: 1, e: "• Concept: Regulation 97 highlights key features of Logistics Post.\n• Elimination: The notes under Regulation 97(2) explicitly state: 'While Speed Post Parcel and India Post Parcel handle products up to 35 Kgs. Logistics Post books Parcels without any specific weight limit. The first slab under Logistics Post, for the purpose of calculation of tariff is 50 Kgs.' This makes option 1 the correct distinctive feature. The other options are not supported by the text or are incorrect." },
  { q: "What is the postage rate for an India Post Parcel (Retail) weighing 750 grams?", o: ["₹36.00","₹52.00","₹68.00","₹84.00"], a: 1, e: "• Concept: Regulation 96(11) provides the rates for India Post Parcels – Retail.\n• Elimination: The rates are: ₹36.00 for a weight not exceeding 500 grams, and ₹16.00 for every additional 500 grams or fraction thereof. For 750 grams:\n    - First 500g: ₹36.00\n    - Remaining 250g (treated as a fraction of 500g): ₹16.00\n    - Total = ₹36.00 + ₹16.00 = ₹52.00." },
  { q: "What demurrage charges are levied if a consignee does not take delivery of a Logistics Post consignment within 48 hours?", o: ["Single the charges for storage.","Double the charges for storage.","Triple the charges for storage.","A fixed penalty of Rs. 100 per day."], a: 1, e: "• Concept: Demurrage charges for Logistics Post are levied when a consignment is not collected within a specified timeframe.\n• Elimination: The regulations state, 'If the consignee does not take the delivery within 48 hours, demurrage charges, equivalent to double the charges for storage, shall be charged.'" },
  { q: "When a consignment is booked under Logistics Post, what is the minimum weight for which each consignment would be charged?", o: ["20 Kgs","30 Kgs","50 Kgs","100 Kgs"], a: 2, e: "• Concept: Logistics Post has a minimum chargeable weight for each consignment.\n• Elimination: The regulations specify, 'When booked under Logistics Post, each consignment would be charged for a minimum weight of 50 Kgs.'" },
  { q: "For Logistics Post, an article/consignment of the size/volume of 10 Cubic feet would be treated as equivalent to how many Kgs?", o: ["20 Kgs","30 Kgs","40 Kgs","50 Kgs"], a: 3, e: "• Concept: Logistics Post uses a weight-volume relationship to determine the chargeable weight.\n• Elimination: The regulations state, 'An article/consignment of the size/volume of 10 Cubic feet would be treated as equivalent to 50 Kgs.'" },
  { q: "What is the limit of liability per transit for insurance offered for Logistics Post through an arrangement with a third-party insurance company?", o: ["Rs. 50 Lakh","Rs. 1 Crore","Rs. 2 Crore","No specific limit, depends on the insurer."], a: 1, e: "• Concept: Logistics Post insurance, when arranged by the Department, has a defined liability limit.\n• Elimination: The regulations clearly state, 'Limit of liability: The limit of liability per transit would be Rs. 1 crore.'" },
  { q: "What is the maximum weight for an item sent as a Speed Post Document, including volumetric weight?", o: ["200 grams","250 grams","500 grams","1000 grams"], a: 2, e: "• Concept: Speed Post Documents have a specific maximum weight limit.\n• Elimination: Regulation 99(2) states, 'The weight of an item for the speed post document shall not exceed 500 grams including volumetric weight.'" },
  { q: "What is the minimum quantity of items required for acceptance under the Direct Post service?", o: ["100 items","500 items","1000 items","5000 items"], a: 2, e: "• Concept: Direct Post is a bulk mail service with a minimum quantity requirement.\n• Elimination: The 'Condition of Articles' section for Direct Post specifies, 'Minimum Quantity - 1000'." },
  { q: "What percentage of commission is an accredited agency eligible for on the media plan value under Media Post?", o: ["5%","10%","15%","20%"], a: 2, e: "• Concept: Media Post offers different commission rates based on the type of agency or individual.\n• Elimination: The 'Agency Commission' section states, 'Accredited Agencies are eligible for 15% commission'." },
  { q: "If a bulk customer's e-Post bill is not paid within the specified time, what penalty is charged?", o: ["10% per annum on outstanding amount, minimum Rs. 50.","12% per annum on outstanding amount, minimum Rs. 100.","15% per annum on outstanding amount, minimum Rs. 150.","A flat penalty of Rs. 500."], a: 1, e: "• Concept: e-Post service includes penalties for delayed payments by bulk customers.\n• Elimination: The e-Post section on 'Penalty' states, 'if bill is not paid within the specified time penalty @ 12% per annum on outstanding amount will be charged subject to a minimum Rs.100/-'." },
  { q: "For how long is the record of e-Post preserved?", o: ["6 months","12 months","24 months","36 months"], a: 1, e: "• Concept: There is a specific retention period for e-Post records.\n• Elimination: The e-Post section on 'Preservation of record of ePOST' states, 'Record of ePOST will be preserved for 12 months.'" },
  { q: "What is the initial period of agreement for offering third-party products or services under Retail Post?", o: ["One year","Two years","Three years","Five years"], a: 2, e: "• Concept: Retail Post agreements with third parties have a defined initial duration.\n• Elimination: Regulation 105(4) states, 'The period of agreement will be three years initially and later it can be extended based on mutual understanding between client and department.'" },
  { q: "How long does the initial registration for Magazine Post remain in force?", o: ["Until December 31 of the current calendar year.","Until December 31 of the first calendar year following registration.","Until December 31 of the second calendar year following registration.","Until December 31 of the third calendar year following registration."], a: 3, e: "• Concept: Magazine Post registration has a specific validity period.\n• Elimination: Regulation 106(5) states, 'The initial Registration will remain in force until December 31 of the third calendar year following the year it was registered.'" },
  { q: "What is the late fee for a Magazine Post renewal application received after the last working day of the month preceding the expiration date?", o: ["Rs. 5","Rs. 10","Rs. 25","No late fee, but treated as a fresh application."], a: 0, e: "• Concept: Magazine Post renewals have a late fee if the application is not submitted on time.\n• Elimination: Regulation 106(6) states, 'No fee is required for renewal however a late fee of Rs.5 will be apply for application received after the last working day of the month preceding the expiration.'" },
  { q: "What is the maximum weight limit for an International Letter?", o: ["500 grams","1 kg","2 kgs","5 kgs"], a: 2, e: "• Concept: International Letters have a specified maximum weight.\n• Elimination: Regulation 108(1) states, 'Letter, which may contain a communication enclosed in an envelope and addressed with a weight limit up to 2 kgs, may be transmitted...'" },
  { q: "What is the maximum permissible weight for an International M-Bag (Bulk Bag)?", o: ["10 kg","20 kg","30 kg","50 kg"], a: 2, e: "• Concept: International M-Bags have a specific maximum weight limit.\n• Elimination: Regulation 114(2) states, 'The maximum permissible weight of an M-bag is 30 kg.'" },
  { q: "Which of the following statements is true regarding postage for International Literature for the Blind?", o: ["It is charged at a concessional rate.","It is exempted from postage.","It is charged at standard letter post rates.","It is charged at a flat rate of Rs. 50."], a: 1, e: "• Concept: International Literature for the Blind receives special postage treatment.\n• Elimination: Regulation 115(4) states, 'The literature for the blind shall be exempted from postage but surface airlift or air surcharge may be availed by paying the applicable fee.'" },
];

export const po_reg_ldce_set4: any[] = [
  { q: "An international tracked packet service (ITPS) was revised in 2025 to boost exports. According to the provided information, for how many countries is ITPS now available?", o: ["25+ countries","35+ countries","45+ countries","55+ countries"], a: 2, e: "• Concept: The 'STATUTORY UPDATE' section under International Tracked Packet Service (ITPS) explicitly states its availability. It mentions, 'ITPS is now available for 45+ countries including USA, UK, Canada, Australia, etc.'\n• Elimination: The other options are incorrect as per the specific number provided in the text." },
  { q: "What is the maximum gross weight prescribed for an International Air Parcel, subject to the maximum acceptable weight limit specified by the country or territory of destination, whichever is lower?", o: ["10 kg","20 kg","30 kg","35 kg"], a: 1, e: "• Concept: Regulation 117(2)(a) states, 'the maximum gross weight of an international air parcel shall be 20 kg, subject to the maximum acceptable weight limit specified by the country or territory of destination, whichever is lower or as amended from time to time.'\n• Elimination: 10 kg, 30 kg, and 35 kg are not the specified maximum weight for international air parcels. 35 kg is the maximum for International Speed Post (EMS)." },
  { q: "As per the Post Office Regulations, 2024, for International Speed Post (EMS), what does the term 'documents' primarily refer to?", o: ["Articles containing information that are dutiable or saleable","Articles containing information that are not dutiable or saleable","Any article or thing transmissible by post, the insurance of which is not compulsory","Items requiring compulsory insurance"], a: 1, e: "• Concept: Regulation 118(1) Explanation (a) defines 'documents' for International Speed Post as 'documents of any kind containing information or data in alphabetical, numerical or technical form, which are not dutiable or saleable'.\n• Elimination: Options suggesting dutiable/saleable items or items requiring compulsory insurance contradict the definition provided. Option 3 describes 'merchandise', not 'documents'." },
  { q: "What is the maximum insurance value for precious metals, precious stones, jewellery, coins, bank notes, currency notes, or securities transmitted by insured International Express Mail Service (EMS)?", o: ["₹50,000","₹75,000","₹1,00,000","No specific limit, depends on administrative instructions"], a: 2, e: "• Concept: Regulation 118(3)(e) states that for such precious items, 'the value of such insurance shall not exceed 1,00,000; Provided that the higher value of insurance may be specified in respect of any such item.'\n• Elimination: The other amounts are not the specified maximum limit. While a higher limit *may* be specified by administrative instructions, the default maximum stated is ₹1,00,000." },
  { q: "For international items containing goods, which customs declaration form is required if the declared value of the item is less than or equal to 300 Special Drawing Rights (SDR)?", o: ["Form CN21","Form CN22","Form CN23","Form CN24"], a: 1, e: "• Concept: Regulation 120(3)(a) specifies, 'CN 22- if the declared value of the international items less than or equal to 300 Special Drawing Rights (SDR)'.\n• Elimination: CN21 and CN24 are not mentioned in the provided text. CN23 is for values greater than 300 SDR." },
  { q: "Which of the following items is explicitly exempted from Electronic Advance Data (EAD) requirements under the Post Office Regulations, 2024?", o: ["International Air Parcels","Small Packets containing merchandise","Letters not subject to customs duties","International Speed Post items"], a: 2, e: "• Concept: Regulation 120(6) states, 'Letters, postcards, printed papers (other than books) or letter-post items containing correspondence or items for the blind, which are not subject to customs duties, shall be exempted from electronic advance data requirements.'\n• Elimination: International Air Parcels, Small Packets containing merchandise, and International Speed Post items generally require EAD, especially if they contain goods." },
  { q: "An addressee of an international air parcel (not addressed 'Poste Restante') fails to take delivery within the stipulated period. From which day will demurrage charges commence, and what is the maximum charge for such an item?", o: ["5th day, maximum ₹24.50","7th day, maximum ₹40","8th day, maximum ₹24.50","8th day, maximum ₹40"], a: 2, e: "• Concept: Regulation 126(1) states that demurrage charges commence 'from the eighth day' after the 7-day grace period. The table under 126(3) S. No. 1 specifies 'Rupee one per day (subject to maximum of twenty four rupees and fifty paise)' for such parcels.\n• Elimination: The grace period is 7 days, so charges start from the 8th day. The maximum charge for a regular international air parcel is ₹24.50, not ₹40 (which is for 'Poste Restante' air parcels)." },
  { q: "For an inward international small packet weighing more than 500 grams, addressed 'Poste Restante', if the addressee fails to take delivery, what is the daily demurrage charge commencing from the eighth day?", o: ["Rupee one per day","Rupees five per day","Rupees ten per day","Rupees twenty per day"], a: 2, e: "• Concept: Regulation 126(2) and the table under 126(3) S. No. 4 specify the demurrage charges for such items. It states 'Rupees ten per day' for an inward international small packet weighing more than 500 grams, addressed 'Poste Restante', commencing from the eighth day.\n• Elimination: Rupee one per day is for international air parcels. Rupees five or twenty per day are not specified for this category of items." },
  { q: "Which of the following is NOT listed as a mail service product under the International Universal Postal Services in the Post Office Regulations, 2024?", o: ["Aerogramme","Small Packet","International Air Parcel","International Tracked Packet"], a: 3, e: "• Concept: Regulation 128(b) lists the international products under Universal Postal Services: (i) Letters, (ii) Aerogramme, (iii) Post Card, (iv) Airmail Post Card, (v) Small Packet, (vi) Printed Papers, (vii) Literature for Blind, (viii) International Air Parcel. International Tracked Packet is not in this list.\n• Elimination: Aerogramme, Small Packet, and International Air Parcel are explicitly listed in the regulation." },
  { q: "According to the Post Office Regulations, 2024, for which of the following services is 'On Postal Service' NOT available?", o: ["Registered Post","Insured Post","Speed Post","None of the above, it is available for all"], a: 2, e: "• Concept: Regulation 130(3) explicitly states, ''On Postal service' shall not be available for items posted under speed post.'\n• Elimination: Regulation 130(1) and 130(2) specify items that may be insured or registered 'On Postal Service', implying its availability for these services for official purposes." },
  { q: "When did the standalone Registered Post service for domestic transmission get discontinued and merged with Speed Post?", o: ["September 1, 2024","January 1, 2025","September 1, 2025","January 1, 2026"], a: 2, e: "• Concept: The 'STATUTORY UPDATE' note under Regulation 132 (Registration of domestic items) clearly states, 'Effective September 1, 2025, the standalone Registered Post service for domestic transmission has been discontinued and merged with Speed Post.'\n• Elimination: The other dates are incorrect as per the specific update provided in the text." },
  { q: "What is the insurance fee for a domestic Speed Post parcel with an insured value of ₹450?", o: ["₹10","₹22","₹28","₹34"], a: 2, e: "• Concept: Regulation 133(1) and the 'INSURANCE FEE (DOMESTIC)' table (i) for Speed Post parcels specify: 'Insured value upto ₹200 ₹10' and 'Insured value above ₹200 ₹10 + ₹6 for every additional ₹100 or fraction thereof'.\n• Calculation: For ₹450:\n    *   First ₹200: ₹10\n    *   Remaining value: ₹450 - ₹200 = ₹250\n    *   For every additional ₹100 or fraction: ₹6. ₹250 covers two full ₹100s and a fraction (₹50), so it's 3 units of ₹100 or fraction. (₹201-300, ₹301-400, ₹401-450)\n    *   Additional fee: 3 * ₹6 = ₹18\n    *   Total fee: ₹10 + ₹18 = ₹28.\n• Elimination: The other options do not correctly apply the specified fee structure." },
  { q: "What is the maximum value for which currency or bank notes can be dispatched by insured domestic post?", o: ["₹10,000","₹20,000","₹50,000","₹1,00,000"], a: 1, e: "• Concept: Regulation 133(2) states, 'Where currency or bank notes are dispatched by insured post, the value shall not exceed twenty thousand rupees.'\n• Elimination: While the overall maximum insurance value for accountable items is ₹1,00,000, there is a specific lower limit for currency or bank notes." },
  { q: "What is the domestic airmail fee chargeable for an item weighing 120 grams?", o: ["₹2","₹3","₹4","₹5"], a: 2, e: "• Concept: Regulation 134, under 'Air Mail fee (Domestic)', specifies: '₹ 2/- for the first fifty grams or fraction thereof, and ₹ 1/- for every additional fifty grams or fraction thereof.'\n• Calculation:\n    *   First 50 grams: ₹2\n    *   Next 50 grams (51-100g): ₹1\n    *   Remaining 20 grams (101-120g) is a fraction of 50 grams: ₹1\n    *   Total fee: ₹2 + ₹1 + ₹1 = ₹4.\n• Elimination: The other options do not correctly apply the fee structure for fractions of 50 grams." },
  { q: "For which international item is no registration fee payable?", o: ["Letters","Small Packets","Aerogrammes","Blind Literature Packet"], a: 3, e: "• Concept: Regulation 138(3) states, 'In addition to the postage, a fee shall be charged for the registration of the international items. Provided that no fees shall be payable for the registration of a blind literature packet.'\n• Elimination: Letters, Small Packets, and Aerogrammes generally incur a registration fee in addition to postage." },
  { q: "What is the maximum compensation payable for an international insured item lost or damaged in transit?", o: ["The insured value of the item.","The actual value of the item.","The amount of loss occasioned by abstraction or damage.","The lowest of the insured value, actual value, or amount of loss."], a: 3, e: "• Concept: Regulation 142(4) states that the compensation payable, in no case, exceeds actual value of the item, insured value, or amount of loss occasioned by the abstraction of, or damage to, the contents of the item, whichever is lower. It also explicitly excludes resultant loss of profits or other indirect loss from assessment. \n• Elimination: Options A, B, and C represent individual limits, but the regulation specifies that the compensation is the lowest among these three values." },
  { q: "Which of the following international insured items is NOT eligible for compensation if lost or damaged?", o: ["An item sent by a civilian internee through a Central Information Agency.","An item addressed to a National Information Bureau regarding prisoners of war.","An item sent by a belligerent received and interned in a neutral country.","All of the above."], a: 3, e: "• Concept: Regulation 142(1) Proviso explicitly states that no compensation shall be paid in respect of letter post, parcel post or express mail service item sent by or addressed to (a) a prisoner of war, (b) a belligerent, received and interned in a neutral country, (c) a civilian internee, and (d) a National Information Bureau or a Central Information Agency regarding prisoners of war. All the options fall under these categories.\n• Elimination: Each of the options A, B, and C individually represents a category for which compensation is not paid. Therefore, 'All of the above' is the correct comprehensive answer." },
  { q: "What is the fee for an Advice of Delivery (Form CN 07) for a registered letter-post item addressed to a foreign country other than Bhutan or Nepal?", o: ["Rs. 10","Rs. 15","Rs. 20","Rs. 25"], a: 2, e: "• Concept: Regulation 144(1) and its accompanying table specify the fees for Advice of Delivery (International). For Bhutan and Nepal, the rate is Rs. 10, and for other foreign countries, it is Rs. 20.\n• Elimination: Options A, B, and D are incorrect as per the specified rates. Rs. 10 is for Bhutan and Nepal, while Rs. 20 is for all other foreign countries." },
  { q: "Under what condition can a sender obtain an inquiry regarding the disposal of an international item to a Universal Postal Union (UPU) member country without paying a fee for Advice of Delivery?", o: ["If the item is an Express Mail Service item.","If the sender has not paid the fee for Advice of Delivery and desires an inquiry.","If the item is lost and a formal complaint is lodged within 30 days.","If the item is addressed to Bhutan or Nepal."], a: 1, e: "• Concept: Regulation 144(3) states that when the sender of such item posted in India and addressed to any country or territory who is a member of Universal Postal Union, has not paid the fee for advice of delivery and desires to have an enquiry made by the Post Office regarding the disposal of item, he shall be entitled to this service without any charge.\n• Elimination: Options A, C, and D do not align with the specific condition mentioned in the regulation for a free inquiry when the Advice of Delivery fee was not initially paid." },
  { q: "What is the maximum amount for which a single domestic money order may be issued?", o: ["Rs. 5,000","Rs. 10,000","Rs. 20,000","Rs. 25,000"], a: 1, e: "• Concept: Regulation 145(2) clearly states that the maximum amount for which a single money order may be issued shall not exceed ten thousand rupees and shall not include a fraction of a rupee.\n• Elimination: Options A, C, and D are incorrect as they do not match the specified maximum limit for a single money order." },
  { q: "What is the total maximum amount that can be remitted through retail money order to a person in a month?", o: ["Rs. 10,000","Rs. 15,000","Rs. 25,000","Rs. 50,000"], a: 2, e: "• Concept: The proviso to Regulation 145(2) specifies that the total amount remitted through retail money order to a person in a month shall not exceed twenty-five thousand rupees.\n• Elimination: While Rs. 10,000 is the limit for a single money order, the question asks for the total monthly limit for retail money orders to a person, which is Rs. 25,000." },
  { q: "What is the commission chargeable on a domestic money order for an amount of Rs. 125?", o: ["Rs. 5","Rs. 6","Rs. 7","Rs. 8"], a: 2, e: "• Concept: Regulation 145(3) states that commission is charged at the rate of Rs. 1 for every twenty rupees of the amount of remittance or fraction thereof. For Rs. 125, we divide 125 by 20, which gives 6.25. Since any fraction counts as a full unit, this means 7 units of Rs. 20. Therefore, the commission is 7 x Rs. 1 = Rs. 7.\n• Elimination: Calculating based on the 'fraction thereof' rule, 125/20 = 6 with a remainder. This means 7 units of Rs. 20 are considered, leading to Rs. 7 commission." },
  { q: "A domestic money order was issued on 15th January. When will its currency period expire?", o: ["15th February","28th February","31st March","15th April"], a: 2, e: "• Concept: Regulation 146 states that the currency period of the money order shall expire upon the end of the last day of the second month following the month of issue. If issued in January, the first month following is February, and the second month following is March. The currency expires at the end of the last day of March.\n• Elimination: The expiry is not based on the exact date of issue but on the end of the second full month following the month of issue." },
  { q: "Within what period must a remitter request a free certificate of payment for a money order from the date of booking?", o: ["One month","Two months","Three months","Six months"], a: 2, e: "• Concept: Regulation 149(b) specifies that a remitter is entitled to obtain a free certificate of payment on request, subject to such request being made within three months from the date of booking.\n• Elimination: The other options do not match the timeline specified in the regulation for requesting a free certificate of payment." },
  { q: "If a payee is not found at the address given on a money order, for how long shall the money order be retained in the post office from the date it is sent out for payment?", o: ["3 days","7 days","15 days","30 days"], a: 1, e: "• Concept: The proviso to Regulation 151(5) states that if the payee is not found at the address given on the money order, the money order shall be retained in the post office for a period not exceeding seven days from the date it is sent out for payment.\n• Elimination: The regulation clearly specifies a 7-day retention period, not any other duration." },
];

export const po_reg_ldce_set5: any[] = [
  { q: "When is the amount of a money order forfeited and treated as revenue to the Government of India?", o: ["If it remains unpaid for 6 months from the date of issue.","If it remains unpaid for 1 year from the date of booking.","If it remains unpaid beyond 3 years from the date of booking.","If it is declared void by the office of issue."], a: 2, e: "• Concept: Regulation 155 states that the amount or value of money order unpaid beyond three years from the date of booking shall be forfeited and after expiry of the said period, such amount or value shall be treated as revenue to the Government of India.\n• Elimination: Option D describes a 'void' money order (Reg 154), which occurs much earlier (end of second month following issue). The forfeiture period is specifically 3 years from booking." },
  { q: "Which of the following is NOT a valid denomination for a single postal order?", o: ["Rs. 10","Rs. 20","Rs. 75","Rs. 100"], a: 2, e: "• Concept: Regulation 157(1) specifies that the amount for which a single postal order may be issued shall be in the denomination of ten rupees, twenty rupees, fifty rupees or one hundred rupees.\n• Elimination: Rs. 75 is not listed as a valid denomination for a single postal order." },
  { q: "A purchaser of a postal order can obtain repayment of its value (excluding commission) after paying a second commission, provided the request is made within what period from the last day of the month of issue?", o: ["Within 12 months","After 12 months but within 24 months","After 24 months but within 36 months","After 36 months"], a: 2, e: "• Concept: Regulation 160(2) states that the purchaser shall also be entitled to repayment of its value after twenty-four months but not after thirty-six months from the last day of the month of issue, provided a second commission is paid.\n• Elimination: Repayment without second commission is within 24 months (Reg 160(1)). Beyond 36 months, the postal order is forfeited (Reg 159)." },
  { q: "A contractual customer availing the Book Now Pay Later (BNPL) facility makes payment at the time of booking. What additional discount will they receive on Speed Post services?", o: ["1%","2%","5%","No additional discount"], a: 0, e: "• Concept: The Administrative Instructions on BNPL Discount Structure state: '1% additional discount will be offered to those contractual customers who either avail advance deposit facility or make payment at the time of booking.'\n• Elimination: The text clearly specifies a 1% additional discount for this condition, not 2% (which is for monthly revenue > Rs. 25 lakh) or other percentages." },
  { q: "According to the Post Office Regulations, 2024, what is mandatory for each item for transmission by post?", o: ["Sender's full address","Recipient's mobile number","Writing of PIN code","Affixing postage stamps"], a: 2, e: "• Concept: Regulation 175(3) explicitly states: 'The writing of PIN code shall be mandatory on each item for transmission by post.'\n• Elimination: While other options might be common practices or requirements for certain services, the regulation specifically mandates the writing of the PIN code for *each item* for transmission by post." },
  { q: "Who is the licensing authority for issuing a license for using a franking machine (RMFM) as per Regulation 176(4) of the Post Office Regulations, 2024?", o: ["Head of the Circle","Director General of Posts","Divisional Head or independent Gazetted Postmaster","Superintendent of Post Offices"], a: 2, e: "• Concept: Regulation 176(4) explicitly states the licensing authority for franking machines. • Elimination: Options (a), (b), and (d) are higher authorities or specific roles not designated as the licensing authority for franking machines in this context." },
  { q: "If franked mail is not presented on the same date due to special circumstances, by when must it be presented in the designated post office as per Regulation 176(8)?", o: ["Within 3 working days","On the very next working day","Within 7 calendar days","Within 24 hours, irrespective of working days"], a: 1, e: "• Concept: Regulation 176(8) specifies the timeline for presenting franked mail. It states 'on the same date or on the very next working day (if is not presented due to special circumstances)'. • Elimination: The other options represent incorrect timelines not mentioned in the regulation for this specific scenario." },
  { q: "An updated version of the Post Office Regulations, containing all amendments made during a particular year, shall be published in which month of the following year as per Regulation 177?", o: ["March","July","January","December"], a: 2, e: "• Concept: Regulation 177 clearly states that the updated version of regulations shall be published 'in the month of January of the following year'. • Elimination: The other months are incorrect as per the regulation." },
  { q: "All Postal Operations Orders issued during January to June shall be compiled and such compilation shall be issued in which month, as per Regulation 178(2)?", o: ["January","April","July","October"], a: 2, e: "• Concept: Regulation 178(2) specifies the half-yearly compilation and issuance months for Postal Operations Orders. Orders issued during January to June are compiled and issued in July. • Elimination: January is for July to December orders, and other months are not specified for compilation issuance." },
  { q: "What is the price of an Embossed Envelope (Domestic) as per TABLE VII of SCHEDULE I of the Post Office Regulations, 2024?", o: ["₹ 2/-","₹ 3/-","₹ 5/-","₹ 10/-"], a: 2, e: "• Concept: TABLE VII of SCHEDULE I explicitly lists the price for Embossed Envelopes (Domestic) as ₹ 5/-. • Elimination: The other options are incorrect prices." },
  { q: "As per TABLE VII of SCHEDULE I, what is the total price for each large Registration Envelope?", o: ["₹ 22/-","₹ 22/- + 50 paise stationery charges","₹ 22/- + ₹ 1/- stationery charge","₹ 23/-"], a: 2, e: "• Concept: TABLE VII of SCHEDULE I specifies the price for a large Registration Envelope as '₹ 22/- + ₹ 1/- stationery charge'. • Elimination: Option (a) is incomplete, (b) is for small envelopes, and (d) is a calculated value but not the explicit breakdown." },
  { q: "A Book Post (Ordinary) weighing 600g was posted with ₹ 37 postage. If the applicable Parcel postage is ₹ 52, what is the amount to be recovered as per the Table for Recovery of Dues?", o: ["₹ 37","₹ 52","₹ 67","₹ 104"], a: 2, e: "• Concept: The Table for Recovery of Dues specifies that for Book Post (Ordinary), the deficiency is calculated as (2 x Postage of later Product) - Postage Product. Here, (2 x ₹ 52) - ₹ 37 = ₹ 104 - ₹ 37 = ₹ 67. • Elimination: The other options do not follow the prescribed calculation for deficiency." },
  { q: "A Postcard weighing 5g was posted with ₹ 1 postage. If it is treated as a Letter with ₹ 5 postage, what is the amount to be recovered as per the Table for Recovery of Dues?", o: ["₹ 4","₹ 5","₹ 8","₹ 9"], a: 3, e: "• Concept: The Table for Recovery of Dues specifies that for a Postcard treated as a Letter, the deficiency is 2 * (Letter Postage - Postcard Postage). Here, 2 * (₹ 5 - ₹ 0.50) = 2 * ₹ 4.50 = ₹ 9. • Elimination: The other options are incorrect calculations based on the table." },
  { q: "Regulation 179 of the Post Office Regulations, 2024, primarily empowers the Central Government or Director General to issue Administrative Instructions regarding which services?", o: ["Financial Services (POSB, Savings Certificates)","International Mail Services","Postal Life Insurance (PLI) & Rural Postal Life Insurance (RPLI)","Business Solutions (Bulk Mail, Franking Machines)"], a: 2, e: "• Concept: Regulation 179 is specifically titled 'Insurance Services' and details the empowerment for PLI & RPLI. Regulation 180 covers Financial Services. • Elimination: Options (a), (b), and (d) are covered by other regulations or are not the primary focus of Regulation 179." },
  { q: "The Post Office Act, 2023, which is the parent act for the Post Office Regulations, 2024, was notified on which date?", o: ["December 16, 2023","January 1, 2024","December 16, 2024","January 1, 2023"], a: 2, e: "• Concept: The 'CHEAT SHEET' section explicitly states 'Parent Act: Post Office Act, 2023 | Notified: Dec 16, 2024'. • Elimination: The other dates are incorrect as per the provided information." },
  { q: "What is the guaranteed delivery timeline for '24 Speed Post' products, and in how many metro cities is it initially available?", o: ["D+2, 4 Metro Cities","D+1, 6 Metro Cities","D+1, All Metro Cities","D+2, 6 Metro Cities"], a: 1, e: "• Concept: The 'Premium Speed Post Products' section defines '24 SPEED POST' as 'Guaranteed delivery on Next Day (D+1)' and states its availability in '6 Metro Cities only'. • Elimination: The other options incorrectly combine the timeline and number of cities." },
  { q: "What is the specified bag color code for '48 Speed Post' products?", o: ["Red","Blue","Green","Orange"], a: 3, e: "• Concept: The 'Premium Speed Post Products' section, under 'Feature', specifies 'Bag Color Code: ORANGE' for 48 Speed Post. • Elimination: Red is for 24 Speed Post, and blue/green are not specified." },
  { q: "What is the incentive per article for a Booking PA (Retail) for booking a '24 Speed Post' article?", o: ["₹ 2.00","₹ 2.50","₹ 3.00","₹ 0.30"], a: 2, e: "• Concept: The 'Staff Incentives' table clearly states 'Booking PA (Retail) ₹ 3.00 per article' for '24 Speed Post'. • Elimination: ₹ 2.00 is for 48 Speed Post, and ₹ 0.30 is for Booking Supervisor for 24 Speed Post." },
  { q: "In case of loss, damage, or pilferage of a Premium Speed Post product, what is the compensation policy?", o: ["Full refund of Speed Post charges","Double the Speed Post charges or ₹ 500, whichever is less","Double the Speed Post charges or ₹ 1000, whichever is less","₹ 1000 flat"], a: 2, e: "• Concept: The 'Compensation Policy (Money Back Guarantee)' section states for Loss/Damage/Pilferage: 'Double the Speed Post charges OR ₹1000 (whichever is less)'. • Elimination: Option (a) is for delay, and options (b) and (d) state incorrect amounts or conditions." },
  { q: "Claims for Premium Speed Post products (24 Speed Post/48 Speed Post) must be resolved within how many working days from the date of filing?", o: ["3 working days","5 working days","7 working days","10 working days"], a: 2, e: "• Concept: The 'Compensation Policy (Money Back Guarantee)' section specifies 'Resolution Time: Claims resolved within 7 working days'. • Elimination: The other options are incorrect timelines for claim resolution." },
  { q: "If the addressee of a Value Payable article is not found, for how long is the article retained in the Post Office?", o: ["3 days","7 days","14 days","1 month"], a: 1, e: "• Concept: Clause 45 of the Post Office Regulations, 2024 specifies that if the addressee of a Value Payable article is not found, the article is retained in the Post Office for 7 days. • Elimination: Other options are incorrect retention periods for VP articles." },
  { q: "What is the maximum amount that can be recovered from the addressee on a Value Payable article?", o: ["Rs. 1,000","Rs. 2,000","Rs. 5,000","Rs. 10,000"], a: 2, e: "• Concept: Clause 43 of the Post Office Regulations, 2024 states that the amount to be recovered from the addressee on a Value Payable article should not exceed Rs. 5,000. • Elimination: The other amounts are not the prescribed maximum limit for VP articles." },
  { q: "For which of the following items is insurance mandatory when sent by post?", o: ["All Parcels above 2 kg","Coin, bullion, platinum, precious stones, jewellery or currency notes","Any article containing documents","Books sent to government libraries"], a: 1, e: "• Concept: Clause 48 of the Post Office Regulations, 2024 mandates insurance for articles containing coin, bullion, platinum, precious stones, jewellery or currency notes. • Elimination: Parcels above 2kg, documents, and books to libraries do not have mandatory insurance requirements under this clause." },
  { q: "What is the maximum limit for insurance of a postal article at a Branch Post Office (BO)?", o: ["Rs. 500","Rs. 600","Rs. 10,000","Rs. 1,00,000"], a: 1, e: "• Concept: Clause 49 of the Post Office Regulations, 2024 specifies that the maximum limit for insurance of a postal article at a Branch Post Office (BO) is Rs. 600. • Elimination: Rs. 500 is close but incorrect. Rs. 10,000 and Rs. 1,00,000 are limits for other services or higher-grade offices." },
  { q: "If a Post Box renter loses the key, what must they do according to the regulations?", o: ["Make a duplicate key themselves","Inform the Post Office and pay for a new lock and key","Break the lock open","Surrender the Post Box"], a: 1, e: "• Concept: Clause 55 of the Post Office Regulations, 2024 states that if a Post Box renter loses the key, they must inform the Post Office and pay for a new lock and key. • Elimination: Making a duplicate, breaking the lock, or immediately surrendering are not the prescribed procedures." },
];

export const po_reg_ldce_set6: any[] = [
  { q: "A \"Delivery Ticket\" is specifically necessary for taking delivery of which type of article?", o: ["Ordinary letters","Registered articles addressed to a Post Box number","Money Orders","Speed Post articles"], a: 1, e: "• Concept: Clause 58 of the Post Office Regulations, 2024 specifies that a \"Delivery Ticket\" is necessary for taking delivery of Registered articles addressed to a Post Box number. • Elimination: Ordinary letters, Money Orders, and Speed Post articles have different delivery procedures and do not typically require a \"Delivery Ticket\" in this specific context." },
  { q: "An instruction given to the Post Office for the redirection of articles is valid for a period of:", o: ["3 months","6 months","1 year","3 years"], a: 0, e: "• Concept: Clause 69 (and Clause 73) of the Post Office Regulations, 2024 states that an instruction given to the Post Office for the redirection of articles is valid for 3 months. • Elimination: Other options represent incorrect validity periods." },
  { q: "What is the current compensation for the loss of a Registered Article, as per standard exam contexts?", o: ["Rs. 25","Rs. 100","Double the registration fee","Actual value of contents"], a: 2, e: "• Concept: Clause 47 of the Post Office Regulations, 2024 (and common exam interpretation) states that compensation for the loss of a Registered Article is double the registration fee. • Elimination: Rs. 25 and Rs. 100 are outdated or incorrect figures. Actual value of contents is typically for insured articles, not registered." },
  { q: "Currency notes can be sent by Insured Post up to a maximum value of:", o: ["Rs. 10,000","Rs. 20,000","Rs. 50,000","Rs. 1,00,000"], a: 1, e: "• Concept: Clause 48 (and Clause 72) of the Post Office Regulations, 2024 specifies that currency notes can be sent by Insured Post up to a value of Rs. 20,000. • Elimination: Other options are incorrect limits for currency notes." },
  { q: "Complaints regarding Value Payable Articles must be made within what period from the date of posting?", o: ["3 months","6 months","1 year","2 years"], a: 1, e: "• Concept: Clause 46 of the Post Office Regulations, 2024 states that complaints regarding Value Payable Articles must be made within 6 months. • Elimination: Other options are incorrect timeframes for VP complaints." },
  { q: "The service of \"Express Delivery\" (special delivery) of unregistered letters/postcards is currently:", o: ["Available in all POs","Discontinued","Available only in Metro cities","Replaced by Speed Post"], a: 1, e: "• Concept: Clause 60 of the Post Office Regulations, 2024 explicitly states that \"Express Delivery\" (special delivery) of unregistered letters/postcards is discontinued. • Elimination: While Speed Post is a premium service, \"Express Delivery\" as a specific service for unregistered articles is discontinued, not merely replaced or limited." },
  { q: "If the addressee refuses to pay the postal charges due on an article, from whom are the charges recovered?", o: ["Are waived","Are recovered from the Postman","Are recovered from the Sender","Become a bad debt"], a: 2, e: "• Concept: Clause 76 of the Post Office Regulations, 2024 clearly states that if the addressee refuses to pay the postal charges due on an article, the charges are recovered from the Sender. • Elimination: Charges are not waived, recovered from the postman, or simply become a bad debt." },
  { q: "Which of the following is an EXCEPTION to the exclusive privilege of the Post Office in conveying letters?", o: ["Letters sent by a courier service","Letters sent by a private friend to be delivered on his way, without hire or reward","Letters containing cheques","Business letters sent by bulk mailers"], a: 1, e: "• Concept: Clause 83 of the Post Office Regulations, 2024, referencing Section 4 of the Indian Post Office Act, 1898, specifies that letters sent by a private friend to be delivered on his way, without hire or reward, are an exception to the exclusive privilege. • Elimination: Courier services for hire, letters with cheques, and bulk business mailers do not fall under the exceptions to the exclusive privilege." },
  { q: "Ordinarily, an undelivered inland postal article (other than Value Payable) is kept in the Post Office for a period of:", o: ["3 days","7 days","14 days","30 days"], a: 1, e: "• Concept: Clause 74 of the Post Office Regulations, 2024 states that ordinarily, an undelivered inland postal article (other than VP) is kept in the Post Office for a period of 7 days. • Elimination: 3 days is too short, 14 days or 30 days are for specific types or foreign articles." },
  { q: "Which of the following living creatures are permitted for transmission by post?", o: ["Snakes","Bees, leeches, and silkworms","White mice","Small birds"], a: 1, e: "• Concept: Clause 101 of the Post Office Regulations, 2024 lists bees, leeches, and silkworms as living creatures that can be transmitted by post under certain conditions. • Elimination: Snakes, white mice, and small birds are generally not permitted due to safety, welfare, or regulatory reasons." },
  { q: "What is the annual fee for a Business Reply Service permit?", o: ["Rs. 100","Rs. 200","Rs. 500","Rs. 1000"], a: 1, e: "• Concept: Clause 121 of the PO Regulations specifies the annual fee for a Business Reply Service permit. • Elimination: The other options are incorrect amounts for this specific fee as per the regulations." },
  { q: "If an unpaid Book Packet is delivered, what is the charge levied on delivery?", o: ["Single the deficiency","Double the deficiency","Triple the deficiency","Returned to sender"], a: 1, e: "• Concept: As per Clause 129, an unpaid Book Packet is charged double the amount of the deficient postage on delivery. • Elimination: Single or triple deficiency are incorrect penalties, and returning to sender is not the primary action for an unpaid article that is otherwise deliverable." },
  { q: "Are air mail charges exempt for Blind Literature Packets?", o: ["Yes, completely exempt","No, air mail surcharge must be paid","Yes, if posted by a government institution","Only for foreign mail"], a: 1, e: "• Concept: Clause 133 states that while Blind Literature Packets are exempt from postage, registration, acknowledgement, and attested receipt fees, air mail surcharges are NOT exempt and must be paid. • Elimination: Options suggesting complete exemption or conditional exemption are incorrect as per the specific rule for air mail charges." },
  { q: "For how many calendar years does the registration of a newspaper for postal purposes remain valid?", o: ["1 calendar year","3 calendar years","5 years","Indefinitely"], a: 1, e: "• Concept: Clause 137 specifies that the registration of a newspaper for postal purposes is valid for 3 calendar years. • Elimination: The other options represent incorrect validity periods." },
  { q: "What is the late fee charged if an application for renewal of newspaper registration is made after the expiry of the previous license?", o: ["Rs. 50","Rs. 100","Rs. 500","Rs. 10"], a: 1, e: "• Concept: As per Clause 137 (and standard departmental fees), the late fee for renewal of newspaper registration is Rs. 100. • Elimination: The other amounts are not the prescribed late fee for this service." },
  { q: "What is the maximum weight for a Registered Parcel posted at or addressed to a Branch Post Office (BO)?", o: ["4 kg","10 kg","20 kg","2 kg"], a: 1, e: "• Concept: Clause 140 differentiates maximum weights for parcels. For a Registered Parcel at a Branch Post Office, the maximum weight is 10 kg. • Elimination: 4 kg is for unregistered parcels, 20 kg is for HO/SO registered parcels, and 2 kg is too low." },
  { q: "The combined length and girth of a parcel must not exceed:", o: ["1.00 meter","1.50 meters","1.80 meters","2.00 meters"], a: 2, e: "• Concept: Clause 141 specifies the maximum dimensions for a parcel. The combined length and girth must not exceed 1.80 meters. • Elimination: The other options are incorrect dimensional limits." },
  { q: "If a parcel weighing more than 4 kg (which requires registration) is found in a letterbox, how will it be treated?", o: ["Returned to the sender","Treated as a Registered Parcel and charged accordingly","Charged as a Registered Parcel plus a compulsory registration fee","Confiscated"], a: 1, e: "• Concept: Clause 142 states that if a parcel required to be registered (e.g., above 4 kg) is found in a letterbox, it will be treated as a Registered Parcel and charged accordingly (i.e., postage for a registered parcel). • Elimination: While a registration fee is part of 'charged accordingly', option (b) is the most accurate general treatment. Confiscation or simple return are not the standard procedures." },
  { q: "Is a Postman bound to give change when receiving payment for a Value Payable article or customs duty?", o: ["Yes, always","Yes, if the amount is less than Rs. 50","No, he is not bound to give change","Yes, if he has sufficient cash"], a: 2, e: "• Concept: Clause 146 explicitly states that a Postman is not bound to give change when receiving payment for articles on which sums are due. • Elimination: Any option suggesting the Postman is bound to give change is incorrect." },
  { q: "If a Registered Article meant for delivery is found to be damaged, what action should the Postman take?", o: ["Will deliver it and take a remark","Will not deliver it but issue a notice to the addressee to attend the PO","Will return it to the sender immediately","Will open it in front of the addressee"], a: 1, e: "• Concept: Clause 151 specifies that if a Registered Article is found damaged, the Postman should not deliver it but instead issue a notice to the addressee to attend the Post Office to take delivery. • Elimination: Delivering with a remark or returning to sender immediately are not the prescribed first steps. Opening it is also not the Postman's initial action." },
  { q: "Generally, a Value Payable (VP) article exceeding what amount is NOT entrusted to the Postman for home delivery but requires an intimation to be sent for window delivery?", o: ["Rs. 100","Rs. 500","Rs. 1000","Rs. 5000"], a: 1, e: "• Concept: As per Clause 152 (standard PO Guide text), VP articles exceeding Rs. 500 are generally not entrusted to the Postman for home delivery, and an intimation is sent to the addressee to collect it from the Post Office. • Elimination: While modern executive orders might allow higher limits, the standard text in the PO Guide Part I often refers to Rs. 500 for this specific rule." },
  { q: "If a Value Payable (VP) article is detained at the request of the addressee beyond the initial 7 days, what fee is charged?", o: ["Late fee","Demurrage / Warehousing charge","Registration fee","No fee"], a: 1, e: "• Concept: Clause 152 states that if a VP article is detained at the request of the addressee beyond the initial 7 days, a demurrage or warehousing charge is levied. • Elimination: Late fee is a general term, and registration fee is for posting. No fee is incorrect." },
  { q: "If a person refuses to pay the postage due on an article delivered to him, what action can the Post Office take?", o: ["Recover it from his bank account","Withhold other articles addressed to him until the due is paid","Call the police","File a lawsuit immediately"], a: 1, e: "• Concept: Clause 145 specifies that if an addressee refuses to pay the postage due, the Post Office can withhold other articles addressed to him until the outstanding amount is paid. • Elimination: The other options are not the immediate or standard departmental actions for this situation." },
  { q: "Can an addressee open a Value Payable (VP) article before paying the amount due?", o: ["Yes, to check contents","No, strictly prohibited","Yes, if the sender permits","Yes, in the presence of the Postmaster"], a: 1, e: "• Concept: Clause 152 explicitly states that a Value Payable article cannot be opened by the addressee before the amount due is paid. • Elimination: Any option allowing opening before payment is incorrect." },
  { q: "What is the maximum value of an Insured article that a Village Postman is authorized to deliver?", o: ["Rs. 500","Rs. 600 (Current limit for BO)","Rs. 200","Rs. 100"], a: 1, e: "• Concept: As per Clause 153 and related Branch Office rules, a Village Postman (who operates from a Branch Office) is authorized to deliver Insured articles up to a value of Rs. 600. • Elimination: The other options are incorrect limits for a Village Postman." },
];

